INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 1, "ペコリーヌのプリン", 5, "やばいですね☆なの！", "おいしすぎて食べ始めたら\n止まらない最高のプリンなの\n今のミヤコを止められるヤツは\n誰もいないの", 100, "プリンセスなプリンなの\nお店にあったいろんな食べもの\nを入れられるだけ入れてみたの\nどんな味なのか楽しみなの", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 2, "コッコロのプリン", 5, "主さま、なの！", "なんだかすごくやさしい気持ち\nになる味なの…\nおはようからおやすみまで\nずっと一緒な味なの…", 101, "いつもオマエのそばに寄りそう\nヤツのぷりんなの。ミヤコの\nワガママもやさしく受け入れて\nくれそうなの", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (0, 3, "キャルのプリン", 5, "ぶっ殺すぞ！なの！\n…デレデレはどこなの？", "いろんな味が一度で楽しめる\nプリンなの。ツンデレはプリン\nにするとおいしいの。ミヤコも\nツンデレを目指してみるの", 102, "ツンツンデレデレなヤツの\nプリンなの。砂糖とスパイスを\n混ぜてみたの。どんな味になる\nか楽しみなの", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 4, "シェフィのプリン", 5, "おにーたん♪なの！", "あったかいところで食べる\nプリンアイスは最高なの～♪\n安心しすぎて昔の記憶のない\nミヤコも心が子どもになるの～", 103, "オマエと同じで、一度赤ちゃん\nみたいになったヤツのプリン\nなの。ヒンヤリ、プリンアイス\nにしてみたの", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 5, "イリヤのプリン", 5, "ハーハッハッハ！\n世界征服なのじゃなのー！", "トマトで栄養補給も完璧なの\nどんどん力がみなぎってきて\n復活も夢じゃないの\nミヤコが復活したら…", 104, "イリヤを見てたら思いついた\nトマトジュースが隠し味の\nプリンなの。栄養満点なの", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 6, "アカリのプリン", 5, "お兄ちゃんのエッチ！　なの！", "見た目がかわいくてもミヤコは\n味にも厳しいの。あむっ…\nこ、これは…！なんだかすごく\n変な気分になってきたの…", 105, "アカリのプリンなの。ヨリと\n同じくらいかわいく作って\nやったの。正直ミヤコは\nおいしければなんでもいいの", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 7, "ヨリのプリン", 5, "えっと…その…あんたのこと…\nだ、大っ嫌いなのーー！", "んむぅ…これはなかなか感想が\n難しいプリンなの…率直に言い\nたいような…心のうちに秘めて\nおきたいような…", 106, "かわいくつくらないとアカリが\n怒りそうだからヨリのプリンは\nかわいく作ったの。自信作なの", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (0, 8, "シノブのプリン", 5, "お父さん…\nいいかげんにしてなの！\nん？プリンの未来は…\n見えなかったの…", "このプリンを食べるとシノブが\nミヤコの中にいるみたいなの！\nシノブの力があれば未来の\nプリンを見放題なの！", 107, "シノブはいつもミヤコに\nやさしくしてくれるから\n丁寧に作ったの。ドクロ親父は\nいらないから作ってないの", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 9, "ジュンのプリン", 5, "インフェルノシールド！なの！", "固すぎてかじれないから丸吞み\nにしたの。なんだか体が硬く\nなった気がするの。みんなを\n守れる気がするの！", 108, "黒い鎧を脱がないヤツのプリン\nなの。固めのプリンを目指したら\nカチカチになりすぎたの", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 10, "トモのプリン", 5, "あなたといると調子が狂うな\n…なの\n翻弄してたのはオマエなの？", "口の中でスパイスがプチプチ\nはじけて新食感なの！\nプチプチがミヤコを\n翻弄するの！", 109, "オマエをいっつもからかってる\nヤツのプリンなの\nちょっぴり変わったスパイスで\nからかいを表現したの", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 11, "マツリのプリン", 5, "タイガーヒーローボンバー！\nなの！", "ん～見かけによらず濃厚な\nパンチのある味わいが\n口いっぱいに広がるの！", 110, "王宮騎士団にいるちっこいヤツ\nなの。ちっこいけどやるヤツ\nらしいから、濃いめの味付けに\nしてみたの", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 13, "クロエのプリン", 5, "ま、いいんじゃん？\nしらんけどなの", "クールな見た目なのにとっても\n優しい味なの！なんだか\n懐かしさを感じるの…", 111, "なんかすごくクールなプリンなの\nなんかテンションも少し\n低そうなの。これ\n食べちゃっても大丈夫なの？", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 14, "チエルのプリン", 5, "ぷりーん★なの！", "なんか変わった食感なの…\nちゃる…ちょる…ちぇる？\nちぇるってしてるの\nでもちぇるってなんなの？", 112, "きれいにデコれたの！\nカラフルでおいしそうなの\nこれは期待できそうなの", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 15, "ユニのプリン", 5, "端的に換言すれば\n青春の味なの？", "味はなんか妙に\n甘酸っぱいの…\n食べたことない味なの\nこの味ってもしかして…", 113, "見た目は完ぺきなの！\nこれをつくったやつは\nきっと天才なの！\n早く食べたいの！", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 16, "サレンのプリン", 5, "幼なじみはあんた…なの？", "ミヤコも幽霊になる前の記憶\nがないのに、なんだか懐かしい\n気持ちになってくるの…", 114, "オマエから聞いた懐かしい\n味ってヤツを全部入れてみたの\nオマエ記憶がないのに懐かしい\nってどういうことなの？", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 17, "スズメのプリン", 5, "ひゃああんなの～！", "おかしいの。このプリンを\n食べてから、３回も転んだの\nミヤコは幽霊だから転んだり\nしないの。なんでなの…？", 115, "たまたま会ったメイドに教えて\nもらった作り方なの。メイドは\nプリンも作れるはずなの。\nなのにこの不安は何なの…？", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (0, 18, "クルミのプリン", 5, "サルキデバレヤ！なの！", "甘さのなかに少しのしょっぱさ\nクセになる味なの\nこのプリンはがんばればきっと\nいろんな美味しいになれるの", 116, "怖がりな子どもが教えてくれた\n小さくてかわいいプリンなの　\n触ってないのにぷるぷる震える\n驚きのやわらかさなの", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 19, "アヤネのプリン", 5, "プリンフルスイングなの～！", "このプリン、食べるとなんだか\nお姉ちゃんになった気分に\nなるの。ピンチのプリンは\nミヤコが守ってやるの！", 117, "くまのぬいぐるみを見ていたら\nひらめいたの。小さいけど\nしっかりした甘さの元気に\nなれるプリンなの！", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 20, "マホのプリン", 5, "みらくるみやりん\nくるりんぱ～☆なの！", "メルヘンパワーがあふれてきて\nいまならミヤコにも魔法が\n使える気がするの！\nほな、いきまひょ～なの！", 118, "マホマホ王国って国にいる\nお姫様のプリンなの\n魔物も虜にしちゃう\nすてきなプリンなの", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 21, "マコトのプリン", 5, "ウルフェンバイトなの！", "うおーん！ミヤコなんだか\n強くなった気がするの！\n困ったことがあればミヤコが\nまとめて面倒見てやるの！", 119, "カッコいいプリンを目指して\nワイルドなものをガンガン\n入れてみたの。きっと熱い\nプリンができるはずなの", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 22, "カオリのプリン", 5, "なんくるないさ～！なの！", "一口食べたら元気が\nあふれて止まらないの！\n気分がいいから、一曲\n踊りでも披露してやるの！", 120, "どっかの国でよくとれる\nゴーヤーに似てるやつを\nいれてみたの！ちょっと\n苦いらしいけど…", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 23, "カスミのプリン", 5, "ふふん。簡単な推理なの", "むむむ…なるほどなの\n上質な糖分をふんだんに\n使うことで、脳をより活性化\nできるからなの！", 121, "勘の鋭いやつが好きな食べ物を\nたくさん入れてみたの\n難しいこと考えるのにぴったり\nらしいけど、なんでなの？", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 24, "マヒルのプリン", 5, "エリザベス～！なの～！", "ミルクがとっても濃厚で\nほっぺたが落ちちゃうの～♪\nこのプリンからは牧場の…\n自然の息吹を感じるの！", 122, "搾りたての牛乳を\nたっぷり使ったプリンなの～\nマヒルに手伝ってもらって\nミヤコ直々に搾ってきたの！", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 25, "シオリのプリン", 5, "私の好きな本…読んで\nもらえたらうれしいです…\nなの", "ほのかな甘さでありながら\nしっかりとした主張も\n感じさせる\n味わい深いプリンなの", 123, "マヒルからやさしいヤツだって\n聞いたの。やさしさを表現\nするために奥ゆかしい甘さに\n仕上げてみたの", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 26, "リマのプリン", 5, "もふもふにしてあげるなの！", "こ、これは…！口の中に入れた\n瞬間にふんわり溶けて\nなくなっちゃうの！\nその食感がやみつきなの！", 124, "牧場にいるヤツらしいの\n牛とは違うらしいの\nもふもふ気持ちいいらしいから\n食感にこだわって作ったの", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (0, 27, "リンのプリン", 5, "めんどくさいな～なの…", "んむぅ…評価が難しい味なの…\nおいしいのはおいしいの…\nん～考えてたら…\n眠くなってきたの…", 125, "いっつも寝てるやつらしいの\nぐっすり眠れる薬草をたくさん\n入れてみたの。プリンとして\nおいしくなるかはわからないの", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 28, "ラビリスタのプリン", 5, "プリンの権能を解放するの～！", "プ…プリンなのにクレープの味\nがするの。味もすごく普通なの\nでも…なんだかプリンの新しい\n扉を開けそうな気がするの…！", 126, "クレープ屋の真っ赤な人に\n教わったプリンなの\n作り方を丁寧に教えてくれて\nとっても優しい人だったの！", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (0, 29, "シズルのプリン", 5, "お姉ちゃんパワー全開！なの！", "とろける食感が絶品なの～♪\n食べるとなんだか幸せな\n気持ちになれるの…これが\n愛情ってやつなの？", 127, "お店に落ちてた謎のレシピの\nプリンなの。レシピの表紙には\n『お姉ちゃんの愛情たっぷり』\nって書いてあったの", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 30, "リノのプリン", 5, "お兄ちゃん、プリンをよこすの！", "これで妹力？があがるらしいの。\n妹になればお兄ちゃんに\nプリンをたかり放題なの！\n最高なの～！", 128, "リノから作り方を教わったの！\nさすがクレープ屋で働いてる\nだけあって美味しそうなの！", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 31, "ヒヨリのプリン", 5, "困った時はお互いさまさま！\nなの！", "食べたら元気が湧いてくるの\nだからプリンのレシピのお礼に\nミヤコも人助けを手伝って\nやったの。ミヤコはえらいの！", 129, "プリンのレシピで悩んでたら\n通りすがりのおねーさんが\n一緒に考えてくれたプリンなの\nいいヤツもたまにはいるの～♪", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 32, "ユイのプリン", 5, "フラワリングヒールなの～♪", "はっ…思わずお花畑が見えたの\n身も心も包まれるような\nとっても優しい味がするの\nこれは…まさに癒しなの～♪", 130, "ミヤコががんばって作った\nこだわりのプリンなの～\nプリンは癒しなの。だから優しい\n気持ちで丁寧に作ったの", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 33, "レイのプリン", 5, "スラッシュテンペスト！なの。", "確かに完璧なプリンなの\nでも究極のプリンと呼ぶには\nまだまだ修行が必要なの…\nプリン作りは奥が深いの…！", 131, "究極のプリンを作るため\nミヤコは厳しい修行をしたの…\nその結果あって完成した\nクールで完璧なプリンなの！", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 34, "アキノのプリン", 5, "おーほっほほほ！なの！", "味にも素材にもこだわりが\nあるの。一流は妥協しないの\nもっと豪華に、もっとおいしく\nできるはず…", 132, "豪華で高級な\nお嬢様プリンなの\n中には宝石みたいな\n大きいイチゴを入れるの！", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 35, "ユカリのプリン", 5, "プリしゅわ最高～！なの！", "プリンは飲み物とも言うの\nぐいっていってみるの\n…ふわしゅわでとろけるの～！\n体に染みわたるの～", 133, "外はしっかり、中はふわとろの\nプリンにするの\n泡みたいなしゅわしゅわの\n生クリームも入れるの♪", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 36, "タマキのプリン", 5, "にゃにゃにゃ！なの！", "このプリンは焼きたてのうちに\n食べるのが一番なの…！\n熱いけどおいしくて\nうずうずしてきたの…！", 134, "餡子を入れて\nオーブンでこんがり焼くの\nたい…焼きプリンなの\n斬新なの！", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (0, 37, "ミフユのプリン", 5, "効率全開！なの！", "プリンはいつでも手軽に\n食べられるのも魅力なの\nこれは食べ応えもあるから一つ\n食べればいっぱい動けるの", 135, "栄養バランスを考えて\n木の実をたくさん入れるの\nあれこれ忙しいときでも\n頼りになるプリンなの！", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 38, "ミサトのプリン", 5, "あらあら～なの～♪", "このプリンを食べてから\nいい子になった気がするの\n大好きなプリンを泣いてる子に\nあげたの。いい気分なの", 136, "エルフの森で子どもにもらった\n薬草を使って作ったの\nこんな優しい味のプリンは\n初めてなの…", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 39, "ハツネのプリン", 5, "スヤスヤ～…なの…", "あまいプリンが口の中で\nぽんぽん弾ける未知の味なの！\n今なら不思議な力で世界も\n救えそうなの！でも眠くなるの…", 137, "お昼寝でみた夢の中に\nでてきた不思議なプリンを\n作ってみたの。見てたらまた\n眠くなってきたの…", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 40, "アオイのプリン", 5, "ぼっちは卒業なの～！", "知らないうちにはしっこに\n隠れちゃってたの。食べたら\nミヤコ、シノブたちに会いに\nいきたくなってきたの", 138, "お店のはしっこに一つだけ\n残ったおもちゃを見て思い\nついたの。他のプリンと一緒に\n置いておくと震えだすの", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 41, "ノゾミのプリン", 5, "リズムあげるのー！", "口の中に華やかな甘さが\n広がる…これがアイドルなの？\n急に歌って踊りたく\nなってきたの！", 139, "トップオブアイドルの\nプリンなの。キラキラした\nものを入れて、あつ～い\nオーブンで焼いてみたの", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 42, "チカのプリン", 5, "風の加護を！なの！", "プリンの生地がとっても\nなめらかで最高の舌触りなの！\n精霊、ミヤコのプリンのために…", 140, "ミヤコにプリンをくれるすごく\nいいヤツのプリンなの\n精霊に呼びかけながら\n一生懸命かき混ぜたの", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 43, "ツムギのプリン", 5, "騎士さんのために\nしたんじゃありません！なの！", "包装は食べるまでの手間が\n増えてめんどくさいの。でも\nそのめんどくささもプリンの\n味を引き立てるの", 141, "歌って踊って衣装も作れるヤツ\nのプリンなの。このプリンは\nきれいに包装するの。プリンを\n最高の形で着飾らせるの", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (0, 12, "クリスティーナのプリン", 5, "宴の始まりなの！", "んむっ！？\nく、口のなかでプリンの\nおいしさが大暴れなの！\n止まらないの！", 142, "プリンをくれないならどうでも\nいいヤツなの。でも横で\nいろいろ言ってきたから\nがんばって作ったの", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 44, "ルカのプリン", 5, "一刀両断、覚悟しな！なの！", "大人の味なの。今やミヤコは\nみんなの頼れる姐御なの！\n悪さするやつはミヤコが\n許さないの！", 143, "大人な甘さ控えめのプリンを\n作るの。試しにお魚を入れて\nみるの。プリンの可能性は\n無限大なの！", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 45, "ナナカのプリン", 5, "きゅぴーん！キタコレ！なの！", "一口食べる度に味が変わって\n魔法みたいなの！\nもしかして全部食べたら\nミヤコも魔法少女になれるの？", 144, "サイカワサイツヨな\n魔法のプリンなの\n中身をカラフルにするの～\n甘いプリンは頭が冴えるの！", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 46, "アンナのプリン", 5, "人呼んで、疾風のミヤコなの！", "一口食べたら謎の組織に\n狙われたり、前世の記憶が蘇る\n気がするの～設定盛りすぎなの\nミヤコは、ミヤコは…", 145, "小難しい言葉をささやきながら\n作ったら魔力あふれるプリンが\n爆誕したの！でも、不思議と\nイタイタしいのはなぜなの～？", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 47, "エリコのプリン", 5, "クスクス…クスクスクス…なの", "なんか普通のプリンよりも\nいい匂いがするの～…\nプリンのことがもっともっと\n好きになっちゃうの…", 146, "甘酸っぱい赤い木の実を\n切り刻んで入れるの\n甘くてちょっぴり刺激的な\nヤンデレのプリンなの", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 48, "ミツキのプリン", 5, "どんなプリンも\nミヤコの隻眼からは\n逃れられないの～！", "鼻に抜ける薬のにおいがアレ\nだけど大人っぽくて頭が\nよくなった気がするの。無性に\n実験したくてしかたないの", 147, "健康に気を遣うミヤコは\nプリンにお薬を入れてみたの～\nでもなんだか毒々しいから\n彩りにバラを添えてみたの～", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 49, "モニカのプリン", 5, "私は子どもではない！なの！", "ん～王道なプリンは\n甘くて安定したおいしさなの～\n思わず笑顔になっちゃうの\nにこにこなの～♪…はっ！", 148, "小さいけどしっかりした\n軍人のプリンなの\nちょっと固めにして\n砂糖はいっぱい入れるの", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 50, "ニノンのプリン", 5, "ショーグン！　ミヤコと一緒に\n天下統一するデースなの！", "このプリンを食べてから\n誰かにお仕えしなきゃ\nいけない気がするデースなの\nそれはショ、ショー…", 149, "オーエド町で手に入れた素材と\nトーゴクに伝わる術をかけて\nプリンを作るの。シュババ！\n忍法隠し味の術なの！", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (0, 51, "クウカのプリン", 5, "…ぐふふ、じゅるり～なの", "カチカチに固めたせいで食感が\nプリンのようで\nプリンじゃないの…でもこの\nもどかしさが癖になるの…", 150, "オマエが持ってきた手錠を\nヒントに作ったプリンなの\nプリンが動けないように\nカチカチに固めたの", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 52, "ユキのプリン", 5, "あぁ、ミヤコはなんて美しいの～", "味も美しい以外の感想が\n出てこないの。ていうかこれを\n食べたミヤコも美しいの！\n鏡、鏡はどこなの！", 151, "とっても美しいプリンなの\n美しいものを手当たり次第\n入れたらすごいことになったの", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (0, 53, "アユミのプリン", 5, "ジー…ってミヤコなにしてるの\nミヤコはストーカーじゃないの！", "うん、やっぱりおいしく…\nん？あそこにいるのは\nアイツなの。あれ？\n体が勝手にアイツの方に…", 152, "知らないうちにお菓子が売れた\n時に思いついたプリンなの。\n作り方もよく覚えてない…\nけど、きっとおいしいの！", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (0, 54, "ミソギのプリン", 5, "にひひ…イタズラの時間なの！", "見た目通り甘々で優しい味なの\nでも、レシピを見たら裏面に\n別の作り方が書いてあるの。\nこれだと激辛プリンに…", 153, "イタズラ好きの手下と一緒に\n作ったプリンなの。見た目は\nかわいいけど、作り方は\n意外と複雑なの～", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (0, 55, "ミミのプリン", 5, "ぴょんぴょこぴょーん、なの♪", "ん～、ふわふわの甘々なの！\nなんだか楽しくなって\n心も体もるんたったしてくるの", 154, "素直でやさしい手下と一緒に\n動物のぬいぐるみをいっぱい\n並べて作ったの", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (0, 56, "キョウカのプリン", 5, "へんたいふしんしゃさんなの！", "ひんやりしてて暑い日でも\nおいしく食べられそうなの！\nん？これを買いたい大人が\nいる？それって…", 155, "幽霊を怖がっている手下と\n一緒に作ったプリンなの。\n小さいクセにきっちりしてて\nとってもかわいいプリンなの", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 57, "スズナのプリン", 5, "ハート狙い撃ち！なの！", "見て食べて楽しめる新機軸の\nプリンなの。ミヤコは幽霊\nだけど自分の足でランウェイを\n歩きたくなってきたの！", 156, "カリスマモデルなプリンなの\nモリモリにデコレーションして\nカリスマ感を演出したの", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (0, 58, "イオのプリン", 5, "授業を始めます♪なの！", "プ、プリンは全部ミヤコのもの\nなのに、なんだかこのプリンは\nいろんな人に教えたく\nなっちゃう不思議な味なの！", 157, "学校の先生をしてるヤツの\nプリンなの。お堅くしようと\nしたら、いつの間にか色っぽく\nなっちゃったの。なんでなの？", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 59, "ミサキのプリン", 5, "立派なレディ、なの！", "ミヤコはプリンならどんなもの\nでも食べるの。でもカラメルを\nちょっとだけ足すの。\nちょっとだけなら…", 158, "少し背伸びしたおませな子を\n表現したプリンなの。あえて\n甘さ控えめなの。カラメルは\n後乗せできるから安心するの", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 60, "ホマレのプリン", 5, "プリンを持ってこないと\nお仕置きだよ～☆なの！", "味はすごいゴージャスなの！\nボスの風格があるの！\nビッグなミヤコに\nプリンを捧げるの！", 159, "謎に包まれたプリンができたの\n何か隠してるようなの…\nこれは危険なプリンなの！", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 61, "カヤのプリン", 5, "たぎってきたの！", "最初の一口目が\nすごいインパクトなの！\n無性にケンカしたくなるの！\nプリンをよこせなの！", 160, "ワイルドな見た目なの！\nこれは期待できそうなの。\nきっと躍動感あふれる味なの！", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (0, 62, "イノリのプリン", 5, "下剋上、やってやるですなの！", "見た目はアレだけど味はおいし\nいの…あと主張もはっきりして\nるの！やる気と自信だけは\n出てきたのうおおおーなの！", 161, "なんか見た目がパッとしないの\nこれほんとに大丈夫なの？\nなんか頼りないの…", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 63, "ムイミのプリン", 5, "どけどけ～！なの～！", "むむむ…食べたら\nやる気が湧いてきたの！\nミヤコを邪魔するやつはみんな\nまとめてぶっ飛ばしてやるの～", 162, "天下の大悪党のプリンなの\nこれまでのジョーシキに\n捉われないプリンを\n作ってみたの～", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 64, "ネネカのプリン", 5, "ミラーミラー！なの！", "いつのまにか作ったの全部\n食べちゃったの。なんで\nプリンは分身しないの？\n無限に増えろなの！", 163, "いろんなものに変身したり\n分身したりできるヤツの\nプリンなの。型で同じプリンを\nたくさんたくさん作ったの", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 65, "クレジッタのプリン", 5, "プリンに忠誠を誓いますわ！\nなの！", "むぅ…認めたくないけど\nおいしいの…これを何個も\n作れるほどのお金を稼ぐのは\n大変なの…でもおいしいから…", 164, "金の亡者のプリンなの\n金にものを言わせて作って\nみたの。おばあちゃんの\nプリンと対極なの", 3);
INSERT INTO `v1_d4ad337c616b1b9ef1f907627b261738e1a1c760b0f568298621747fe476f277` VALUES (1, 66, "カリンのプリン", 5, "ギルド管理協会へようこそ！\nなの！", "手堅い…！手堅いの…！\n隙のないプリンなの！\n今のミヤコなら完璧な\n書類作成ができそうなの！", 165, "みんなお世話になるギルド\n管理協会職員のプリンなの\nお役所感を出すために手堅く\n王道に作ったの", 3);
